-- Read-only DM8 verification for an already authenticated administrative session.
-- Inspect SQL errors and adapt view names/columns to the installed version.
SET LINESIZE 320;
SET PAGESIZE 1000;
SET TIMING OFF;

PROMPT INSTANCE;
SELECT NAME, INSTANCE_NAME, STATUS$, MODE$ FROM V$INSTANCE;
SELECT NAME, ARCH_MODE, CREATE_TIME FROM V$DATABASE;
SELECT * FROM V$VERSION;

PROMPT INITIALIZATION_VALUES;
SELECT SF_GET_PAGE_SIZE() AS PAGE_SIZE_BYTES,
       SF_GET_EXTENT_SIZE() AS EXTENT_PAGES,
       SF_GET_CASE_SENSITIVE_FLAG() AS CASE_SENSITIVE,
       SF_GET_UNICODE_FLAG() AS CHARSET_FLAG,
       SF_GET_PARA_VALUE(2, 'ENABLE_PAGE_CHECK') AS PAGE_CHECK_MODE;

PROMPT RUNTIME_AND_FILE_PARAMETERS;
SELECT PARA_NAME, PARA_VALUE, FILE_VALUE, SESS_VALUE, PARA_TYPE,
       MIN_VALUE, MAX_VALUE
FROM V$DM_INI
WHERE PARA_NAME IN (
    'GLOBAL_CHARSET', 'GLOBAL_STR_CASE_SENSITIVE', 'LENGTH_IN_CHAR',
    'NVARCHAR_LENGTH_IN_CHAR', 'TIME_ZONE', 'BLANK_PAD_MODE',
    'CASE_COMPATIBLE_MODE', 'COMPATIBLE_MODE', 'CALC_AS_DECIMAL',
    'CAST_DIGIT_MODE', 'ORDER_BY_NULLS_FLAG', 'PK_WITH_CLUSTER',
    'DATETIME_FAST_RESTRICT', 'PAGE_CHECK_POLICY', 'PAGE_CHECK_ID',
    'ENABLE_AUDIT', 'AUDIT_FILE_FULL_MODE', 'AUDIT_SPACE_LIMIT',
    'ENABLE_LOCAL_OSAUTH', 'PWD_MIN_LEN', 'PWD_POLICY',
    'PORT_NUM', 'MAX_OS_MEMORY', 'BUFFER', 'MEMORY_POOL', 'MEMORY_TARGET',
    'CACHE_POOL_SIZE', 'MAX_SESSIONS', 'TEMP_SIZE', 'TEMP_SPACE_LIMIT',
    'SORT_BUF_SIZE', 'SORT_BUF_GLOBAL_SIZE', 'HJ_BUF_SIZE',
    'HJ_BUF_GLOBAL_SIZE', 'HAGR_BUF_SIZE', 'HAGR_BUF_GLOBAL_SIZE', 'ARCH_INI'
)
ORDER BY PARA_NAME;

PROMPT PASSWORD_VALUES;
SELECT NAME, VALUE FROM V$PARAMETER
WHERE NAME IN ('PWD_POLICY', 'PWD_MIN_LEN', 'ENABLE_AUDIT')
ORDER BY NAME;

PROMPT PROFILES;
SELECT PROFILE, RESOURCE_NAME, LIMIT FROM DBA_PROFILES
WHERE RESOURCE_TYPE='PASSWORD'
ORDER BY PROFILE, RESOURCE_NAME;

PROMPT USERS;
SELECT USERNAME, PROFILE, ACCOUNT_STATUS, DEFAULT_TABLESPACE,
       TEMPORARY_TABLESPACE, CREATED FROM DBA_USERS ORDER BY USERNAME;

PROMPT SCHEMAS;
SELECT OWNER, OBJECT_NAME FROM DBA_OBJECTS
WHERE OBJECT_TYPE='SCH' ORDER BY OWNER, OBJECT_NAME;

PROMPT OBJECT_COUNTS;
SELECT OWNER, OBJECT_TYPE, COUNT(*) AS OBJECT_COUNT FROM DBA_OBJECTS
GROUP BY OWNER, OBJECT_TYPE ORDER BY OWNER, OBJECT_TYPE;

PROMPT DIRECT_ROLE_GRANTS;
SELECT GRANTEE, GRANTED_ROLE, ADMIN_OPTION FROM DBA_ROLE_PRIVS
WHERE GRANTEE IN (SELECT USERNAME FROM DBA_USERS)
ORDER BY GRANTEE, GRANTED_ROLE;

PROMPT DIRECT_SYSTEM_GRANTS;
SELECT GRANTEE, PRIVILEGE, ADMIN_OPTION FROM DBA_SYS_PRIVS
WHERE GRANTEE IN (SELECT USERNAME FROM DBA_USERS)
ORDER BY GRANTEE, PRIVILEGE;

PROMPT REDO_FILES;
SELECT * FROM V$RLOGFILE;

PROMPT ARCHIVE_CONFIGURATION;
SELECT * FROM V$DM_ARCH_INI;

PROMPT DATA_FILES;
SELECT TABLESPACE_NAME, FILE_NAME, BYTES, AUTOEXTENSIBLE, MAXBYTES
FROM DBA_DATA_FILES ORDER BY TABLESPACE_NAME, FILE_NAME;

PROMPT SESSION_BEHAVIOR;
SELECT CASE WHEN 'abc'='ABC' THEN 1 ELSE 0 END AS CASE_EQUAL,
       10/3 AS DIV_RESULT;

-- Keep the session open so the operator can inspect or adapt failed queries.
